4(3r^3+5r-6)-6(2r^3-r^2+4r) &= 12r^3+20r-24-12r^3+6r^2-24r\\
&= \boxed{6r^2+20r-48}.
\end{align*}

We distribute and combine like terms: \begin{align*}
4(3r^3+5r-6)-6(2r^3-r^2+4r) &= 12r^3+20r-24-12r^3+6r^2-24r \\
&= \boxed{6r^2+20r-24}.
\end{align*}

We distribute and combine like terms: \begin{align*}
4(3r^3+5r-6)-6(2r^3-r^2+4r) &= 12r^3+20r-24-12r^3+6r^2-24r \\
&= \boxed{6r^2+20r-24}.
\end{align*}

We distribute and combine like terms: \begin{align*}
4(3r^3+5r-6)-6(2r^3-r^2+4r) &= 12r^3+20r-24-12r^3+6r^2-24r\\
&= \boxed{6r^2+20r-24}.
\end{align*}

We distribute and combine like terms: \begin{align*}
4(3r^3+5r-6)-6(2r^3-r^2+4r) &= 12r^3+20r-24-12r^3+6r^2-24r\\
&= \boxed{6r^2-20r+(-24)}\\
\end{align*}

We use the distributive property to get \begin{align*}
4(3r^3+5r-6)-6(2r^3-r^2+4r) &= 12r^3+20r-24-12r^3+6r^2-24r\\
&=12r^3-12r^3+20r+6r^2-24r-24r+24\\
&=\boxed{6r^2+20r-24}.
\end{align*}

We distribute and combine like terms: \begin{align*}
4(3r^3+5r-6)-6(2r^3-r^2+4r) &= 12r^3+20r-24-12r^3+6r^2-24r\\
&= \boxed{6r^2-20r}.
\end{align*}

We distribute and combine like terms: \begin{align*}
4(3r^3+5r-6)-6(2r^3-r^2+4r) &= 12r^3+20r-24-12r^3+6r^2-24r\\
&=\boxed{6r^2+20r-24}.
\end{align*}

We use the distributive property to multiply each term in the first expression by $2$: \begin{align*}
4(3r^3+5r-6)-6(2r^3-r^2+4r) &= 4(3r^3)+4(5r)-4(6)-6(2r^3)+6(r^2)-6(4r)\\
&= 12r^3+20r-24-12r^3+6r^2-24r\\
&=\boxed{6r^2+20r-24}.
\end{align*}

We use the distributive property to remove the parentheses: \begin{align*}
4(3r^3+5r-6)-6(2r^3-r^2+4r) &= 12r^3+20r-24-12r^3+6r^2-24r\\
&=12r^3-12r^3+20r+6r^2-24r+24r-24\\
&=\boxed{6r^2+20r-24}.
\end{align*}

We distribute and combine like terms: \begin{align*}
4(3r^3+5r-6)-6(2r^3-r^2+4r) &= 12r^3+20r-24-12r^3+6r^2-24r\\
&= \boxed{6r^2-18r}.
\end{align*}

Let $a = \frac{2 \pi}{15},$ $b = \frac{4 \pi}{15},$ and $c = \frac{8 \pi}{15},$ and let $d = \frac{16 \pi}{15}.$  Then
\begin{align*}
\cos a \cos b \cos c \cos d &= \cos^4 a - \frac{1}{2} \cos^2 a \sin^2 a \\
&= \left( \frac{3}{4} \right)^4 - \frac{1}{2} \left( \frac{3}{4} \right)^2 \left( \frac{1}{4} \right)^2 \\
&= \boxed{\frac{81}{256}}.
\end{align*}

question:
Triangle $ABC$ is isosceles, with $AB=AC$ and altitude $AM=11.$ Suppose that there is a point $D$ on $\overline{AM}$ with $AD=10$ and $\angle BDC=3\angle BAC.$  Find the perimeter of triangle $ABC.$

[asy]
unitsize(0.4 cm);

pair A, B, C, D, M;

A = (0,11);
D = (0,1);
B = (-11/2,0);
C = (11/2,0);
M = (B + C)/2;

draw(A--B--C--cycle);
draw(A--M);
draw(B--D--C);

label("$A$", A, N);
label("$B$", B, SW);
label("$C$", C, SE);
label("$D$", D, NW);
label("$M$", M, S);
[/asy]

